"""Helpers for converting model responses into package-native types."""

from __future__ import annotations

from typing import Any, Mapping

from verifiers.utils.message_utils import content_to_text


def _first_choice(response: Any) -> Any:
    if hasattr(response, "choices"):
        return response.choices[0]
    if isinstance(response, Mapping):
        return response["choices"][0]
    raise TypeError(f"Unsupported response type: {type(response)!r}")


def extract_chat_message(response: Any) -> dict[str, Any]:
    """Extract an assistant chat message from an OpenAI-style response."""

    choice = _first_choice(response)
    if hasattr(choice, "message"):
        message = choice.message
        tool_calls = getattr(message, "tool_calls", None)
        return {
            "role": getattr(message, "role", "assistant") or "assistant",
            "content": content_to_text(getattr(message, "content", "")),
            **({"tool_calls": tool_calls} if tool_calls is not None else {}),
        }
    message = choice.get("message", {})
    tool_calls = message.get("tool_calls")
    return {
        "role": message.get("role", "assistant"),
        "content": content_to_text(message.get("content")),
        **({"tool_calls": tool_calls} if tool_calls is not None else {}),
    }


def extract_text_completion(response: Any) -> str:
    """Extract a text completion from an OpenAI-style response."""

    choice = _first_choice(response)
    if hasattr(choice, "text"):
        return content_to_text(choice.text)
    return content_to_text(choice.get("text", ""))

