from __future__ import annotations

from typing import Any


def build_info(
    row: dict[str, Any],
    *,
    info_columns: list[str] | None = None,
    reserved: set[str] | None = None,
) -> dict[str, Any]:
    """Extract side-channel metadata from a dataset row."""

    reserved = reserved or set()
    if info_columns is not None:
        return {column: row[column] for column in info_columns if column in row}
    return {key: value for key, value in row.items() if key not in reserved}

