"""Dataset helpers."""

from __future__ import annotations

from typing import Any

from datasets import Dataset


def ensure_dataset(data: Dataset | list[dict[str, Any]] | dict[str, Any]) -> Dataset:
    """Convert common input shapes into a HuggingFace dataset."""

    if isinstance(data, Dataset):
        return data
    if isinstance(data, list):
        return Dataset.from_list(data)
    if isinstance(data, dict):
        if data and all(isinstance(value, list) for value in data.values()):
            return Dataset.from_dict(data)
        return Dataset.from_list([data])
    raise TypeError(f"Unsupported dataset input type: {type(data)!r}")


def dataset_to_rows(dataset: Dataset) -> list[dict[str, Any]]:
    """Materialize a dataset as a list of dictionaries."""

    try:
        return dataset.to_list()
    except AttributeError:
        return [dict(row) for row in dataset]

