"""Tool execution helpers."""

from __future__ import annotations

import inspect
from typing import Any, Callable


def get_tool_name(func: Callable[..., Any]) -> str:
    """Return the public tool name for a callable."""

    return getattr(func, "__name__", func.__class__.__name__)


def call_tool(func: Callable[..., Any], arguments: dict[str, Any]) -> Any:
    """Invoke a tool with only the arguments it declares."""

    signature = inspect.signature(func)
    if any(param.kind == inspect.Parameter.VAR_KEYWORD for param in signature.parameters.values()):
        return func(**arguments)
    filtered = {key: value for key, value in arguments.items() if key in signature.parameters}
    return func(**filtered)

