"""Asynchronous helpers."""

from __future__ import annotations

import asyncio
import inspect
from typing import Any, Awaitable, Callable, Iterable


async def maybe_await(value: Any) -> Any:
    """Await values only when needed."""

    if inspect.isawaitable(value):
        return await value
    return value


def filter_kwargs(func: Callable[..., Any], values: dict[str, Any]) -> dict[str, Any]:
    """Pass only arguments that the target callable accepts."""

    try:
        signature = inspect.signature(func)
    except (TypeError, ValueError):
        return values

    if any(param.kind == inspect.Parameter.VAR_KEYWORD for param in signature.parameters.values()):
        return values

    allowed = set(signature.parameters)
    return {key: value for key, value in values.items() if key in allowed}


async def gather_with_concurrency(limit: int, coroutines: Iterable[Awaitable[Any]]) -> list[Any]:
    """Gather coroutines with optional concurrency control."""

    coroutines = list(coroutines)
    if not coroutines:
        return []
    if limit is None or limit < 1:
        return list(await asyncio.gather(*coroutines))

    semaphore = asyncio.Semaphore(limit)

    async def run(coro: Awaitable[Any]) -> Any:
        async with semaphore:
            return await coro

    return list(await asyncio.gather(*(run(coro) for coro in coroutines)))

