"""Helpers for chat-style messages."""

from __future__ import annotations

import copy
import json
from typing import Any

from verifiers.types import ChatMessage, Messages


def clone_messages(messages: list[ChatMessage]) -> list[ChatMessage]:
    """Deep copy chat messages."""

    return copy.deepcopy(messages)


def _content_part_to_text(part: Any) -> str:
    if isinstance(part, str):
        return part
    if isinstance(part, dict):
        if "text" in part:
            return str(part["text"])
        return json.dumps(part, sort_keys=True, default=str)
    return str(part)


def content_to_text(content: Any) -> str:
    """Normalize content into a plain string."""

    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return "".join(_content_part_to_text(part) for part in content)
    return str(content)


def role_messages(messages: list[ChatMessage], role: str) -> list[ChatMessage]:
    """Return messages for a given role."""

    return [message for message in messages if message.get("role") == role]


def last_role_message(messages: list[ChatMessage], role: str) -> ChatMessage | None:
    """Return the last message for a role."""

    for message in reversed(messages):
        if message.get("role") == role:
            return message
    return None


def messages_to_text(messages: Messages) -> str:
    """Serialize chat messages into readable plain text."""

    if isinstance(messages, str):
        return messages
    parts: list[str] = []
    for message in messages:
        role = message.get("role", "unknown")
        content = content_to_text(message.get("content"))
        if content:
            parts.append(f"{role}: {content}")
    return "\n".join(parts).strip()

