"""Test-friendly async OpenAI client implementation."""

from __future__ import annotations

import json
from dataclasses import dataclass
from types import SimpleNamespace
from typing import Any


@dataclass(slots=True)
class _StoredResponse:
    content: str
    finish_reason: str = "stop"
    tool_calls: list[dict[str, Any]] | None = None


def _messages_to_key(messages: list[dict[str, Any]]) -> str:
    normalized = [
        {
            "role": message.get("role"),
            "content": message.get("content"),
            "tool_calls": message.get("tool_calls"),
            "name": message.get("name"),
        }
        for message in messages
    ]
    return json.dumps(normalized, sort_keys=True, default=str)


def _build_chat_response(stored: _StoredResponse):
    message = SimpleNamespace(
        role="assistant",
        content=stored.content,
        tool_calls=stored.tool_calls,
    )
    choice = SimpleNamespace(message=message, finish_reason=stored.finish_reason)
    return SimpleNamespace(choices=[choice])


def _build_text_response(stored: _StoredResponse):
    choice = SimpleNamespace(text=stored.content, finish_reason=stored.finish_reason)
    return SimpleNamespace(choices=[choice])


class _ChatCompletionsAPI:
    def __init__(self, client: "MockAsyncOpenAI") -> None:
        self._client = client

    async def create(self, *, model: str, messages: list[dict[str, Any]], **kwargs):
        del model, kwargs
        self._client.chat_calls.append(messages)
        stored = self._client.chat_completions.get(
            _messages_to_key(messages),
            self._client.default_chat_response,
        )
        return _build_chat_response(stored)


class _TextCompletionsAPI:
    def __init__(self, client: "MockAsyncOpenAI") -> None:
        self._client = client

    async def create(self, *, model: str, prompt: str, **kwargs):
        del model, kwargs
        self._client.text_calls.append(prompt)
        stored = self._client.text_completions.get(prompt, self._client.default_text_response)
        return _build_text_response(stored)


class MockAsyncOpenAI:
    """Deterministic async OpenAI-compatible client used for tests.

    The client supports both `client.chat.completions.create(...)` and
    `client.completions.create(...)`.
    """

    def __init__(self) -> None:
        self.chat_completions: dict[str, _StoredResponse] = {}
        self.text_completions: dict[str, _StoredResponse] = {}
        self.default_chat_response = _StoredResponse(content="Mock chat response")
        self.default_text_response = _StoredResponse(content="Mock text response")
        self.chat_calls: list[list[dict[str, Any]]] = []
        self.text_calls: list[str] = []
        self.base_url = "http://localhost/v1/"
        self.chat = SimpleNamespace(completions=_ChatCompletionsAPI(self))
        self.completions = _TextCompletionsAPI(self)

    def add_chat_response(
        self,
        messages: list[dict[str, Any]],
        response: str,
        finish_reason: str = "stop",
        tool_calls: list[dict[str, Any]] | None = None,
    ) -> None:
        self.chat_completions[_messages_to_key(messages)] = _StoredResponse(
            content=response,
            finish_reason=finish_reason,
            tool_calls=tool_calls,
        )

    def add_text_response(
        self,
        prompt: str,
        response: str,
        finish_reason: str = "stop",
    ) -> None:
        self.text_completions[prompt] = _StoredResponse(
            content=response,
            finish_reason=finish_reason,
        )

    def set_default_responses(self, *, chat: str | None = None, text: str | None = None) -> None:
        if chat is not None:
            self.default_chat_response = _StoredResponse(content=chat)
        if text is not None:
            self.default_text_response = _StoredResponse(content=text)

