"""Structured XML parser."""

from __future__ import annotations

import re
from types import SimpleNamespace
from typing import Callable, Iterable

from verifiers.parsers.parser import Parser
from verifiers.types import Messages
from verifiers.utils.message_utils import content_to_text


class XMLParser(Parser):
    """Extract structured fields from XML-like text fragments."""

    def __init__(
        self,
        fields: list[str | tuple[str, ...]],
        answer_field: str = "answer",
        extract_fn: Callable[[str], str] = lambda x: x,
    ) -> None:
        super().__init__(extract_fn=extract_fn)
        if not fields:
            raise ValueError("XMLParser requires at least one field.")
        self.fields = list(fields)
        self._field_aliases: dict[str, tuple[str, ...]] = {}
        for field in self.fields:
            if isinstance(field, str):
                self._field_aliases[field] = (field,)
            else:
                self._field_aliases[field[0]] = tuple(field)
        self.answer_field = self._canonical_name(answer_field)

    def _canonical_name(self, field_name: str) -> str:
        for canonical, aliases in self._field_aliases.items():
            if field_name in aliases:
                return canonical
        return field_name

    def _extract_tag(self, text: str, tags: Iterable[str]) -> str | None:
        for tag in tags:
            pattern = re.compile(
                rf"<{re.escape(tag)}\b[^>]*>(.*?)</{re.escape(tag)}>",
                flags=re.IGNORECASE | re.DOTALL,
            )
            match = pattern.search(text)
            if match is not None:
                return match.group(1).strip()
        return None

    def parse(self, text: str) -> SimpleNamespace:
        """Parse text into a namespace with one attribute per configured field."""

        data: dict[str, str | None] = {}
        for canonical, aliases in self._field_aliases.items():
            data[canonical] = self._extract_tag(text, aliases)
        return SimpleNamespace(**data)

    def parse_answer(self, completion: Messages) -> str | None:
        """Return the extracted answer field from XML-like content."""

        if isinstance(completion, str):
            raw_text = completion
        else:
            assistant_messages = self.get_assistant_messages(completion)
            if not assistant_messages:
                return None
            raw_text = content_to_text(assistant_messages[-1].get("content"))
        parsed = self.parse(raw_text)
        answer = getattr(parsed, self.answer_field, None)
        if answer is None:
            return None
        return self.extract_fn(answer)

    def get_format_reward_func(self):
        """Reward outputs that contain the configured answer field."""

        def format_reward(completion: Messages, **kwargs) -> float:
            del kwargs
            answer = self.parse_answer(completion)
            return 1.0 if answer is not None else 0.0

        return format_reward

