from __future__ import annotations

from verifiers.rubrics.rubric import Rubric


def tool_call_present(raw_completion=None, **kwargs) -> float:
    del kwargs
    if isinstance(raw_completion, list):
        return 1.0 if any(message.get("tool_calls") for message in raw_completion) else 0.0
    return 0.0


class ToolRubric(Rubric):
    """A convenience rubric for rewarding valid tool invocation."""

    def __init__(self, **kwargs):
        super().__init__(funcs=[tool_call_present], weights=[1.0], **kwargs)

