"""Base text parser."""

from __future__ import annotations

from typing import Any, Callable

from verifiers.types import ChatMessage, Messages
from verifiers.utils.message_utils import content_to_text, role_messages


class Parser:
    """Basic parser for raw text and chat completions."""

    def __init__(self, extract_fn: Callable[[str], str] = lambda x: x) -> None:
        self.extract_fn = extract_fn

    def parse(self, text: str) -> Any:
        """Parse direct text output."""

        return self.extract_fn(text)

    def _last_assistant_text(self, completion: list[ChatMessage]) -> str | None:
        assistant_messages = self.get_assistant_messages(completion)
        if not assistant_messages:
            return None
        return content_to_text(assistant_messages[-1].get("content"))

    def parse_answer(self, completion: Messages) -> str | None:
        """Parse the final assistant answer from a completion."""

        if isinstance(completion, str):
            return self.parse(completion)
        text = self._last_assistant_text(completion)
        if text is None:
            return None
        return self.parse(text)

    def get_format_reward_func(self) -> Callable[..., float]:
        """Return a simple formatting reward function for this parser."""

        def format_reward(completion: Messages, **kwargs) -> float:
            del kwargs
            parsed = self.parse_answer(completion)
            return 1.0 if parsed not in (None, "") else 0.0

        return format_reward

    def get_assistant_messages(self, completion: list[ChatMessage]) -> list[ChatMessage]:
        return role_messages(completion, "assistant")

    def get_system_messages(self, completion: list[ChatMessage]) -> list[ChatMessage]:
        return role_messages(completion, "system")

    def get_user_messages(self, completion: list[ChatMessage]) -> list[ChatMessage]:
        return role_messages(completion, "user")

    def get_tool_messages(self, completion: list[ChatMessage]) -> list[ChatMessage]:
        return role_messages(completion, "tool")

